    10→type URLParams = {
    11→  search: string;
    12→  type: string;
    13→  category: string;
    14→  priceMin: string;
    15→  priceMax: string;
    16→  surfaceMin: string;
    17→  surfaceMax: string;
    18→  rooms: string;
    19→  bedrooms: string;
    20→  city: string;
    21→  selectedCitiesJson: string;
    22→  selectedTypesJson: string;
    23→  selectedCategoriesJson: string;
    24→  selectedPublisherTypesJson: string;
    25→  selectedEquipmentJson: string;
    26→  page: number;
    27→  sortBy: string;
    28→  sortOrder: "asc" | "desc";
    29→  view: "list" | "grid";
    30→};
    31→
    32→export function urlParamsToFilters(
    33→  urlParams: URLParams,
    34→): PropertySearchFilters {
    35→  let selectedCities: MoteurImmoCity[] = [];
    36→  let selectedTypes: PropertyType[] = [];
    37→  let selectedCategories: PropertyCategory[] = [];
    38→  let selectedPublisherTypes: PublisherType[] = [];
    39→  let selectedEquipment: EquipmentOption[] = [];
    40→
    41→  // Parse JSON arrays
    42→  if (urlParams.selectedCitiesJson) {
    43→    try {
    44→      selectedCities = JSON.parse(
    45→        urlParams.selectedCitiesJson,
    46→      ) as MoteurImmoCity[];
    47→    } catch {
    48→      selectedCities = [];
    49→    }
    50→  }
    51→
    52→  if (urlParams.selectedTypesJson) {
    53→    try {
    54→      selectedTypes = JSON.parse(urlParams.selectedTypesJson) as PropertyType[];
    55→    } catch {
    56→      selectedTypes = [];
    57→    }
    58→  }
    59→
    60→  if (urlParams.selectedCategoriesJson) {
    61→    try {
    62→      selectedCategories = JSON.parse(
    63→        urlParams.selectedCategoriesJson,
    64→      ) as PropertyCategory[];
    65→    } catch {
    66→      selectedCategories = [];
    67→    }
    68→  }
    69→
    70→  if (urlParams.selectedPublisherTypesJson) {
    71→    try {
    72→      selectedPublisherTypes = JSON.parse(
    73→        urlParams.selectedPublisherTypesJson,
    74→      ) as PublisherType[];
    75→    } catch {
    76→      selectedPublisherTypes = [];
    77→    }
    78→  }
    79→
    80→  if (urlParams.selectedEquipmentJson) {
    81→    try {
    82→      selectedEquipment = JSON.parse(
    83→        urlParams.selectedEquipmentJson,
    84→      ) as EquipmentOption[];
    85→    } catch {
    86→      selectedEquipment = [];
    87→    }
    88→  }
    89→
    90→  return {
    91→    search: urlParams.search,
    92→
    93→    // Nouvelles sélections multiples
    94→    selectedTypes,
    95→    selectedCategories,
    96→    selectedPublisherTypes,
    97→    selectedEquipment,
    98→    selectedEnergyGrades: [], // TODO: Ajouter si nécessaire
    99→
   100→    // Prix
   101→    priceMin: urlParams.priceMin,
   102→    priceMax: urlParams.priceMax,
   103→
   104→    // Surfaces
   105→    surfaceMin: urlParams.surfaceMin,
   106→    surfaceMax: urlParams.surfaceMax,
   107→    landSurfaceMin: "", // TODO: Ajouter aux URL params si nécessaire
   108→    landSurfaceMax: "", // TODO: Ajouter aux URL params si nécessaire
   109→
   110→    // Pièces
   111→    rooms: urlParams.rooms,
   112→    bedrooms: urlParams.bedrooms,
   113→
   114→    // Localisation
   115→    city: urlParams.city,
   116→    selectedCities,
   117→    radius: "", // TODO: Ajouter aux URL params si nécessaire
   118→
   119→    // Performance énergétique (ranges)
   120→    energyGradeMin: "",
   121→    energyGradeMax: "",
   122→
   123→    // Construction
   124→    constructionYearMin: "",
   125→    constructionYearMax: "",
   126→    floor: "",
   127→
   128→    // Anciens champs (compatibility)
   129→    type: urlParams.type as PropertySearchFilters["type"],
   130→    category: urlParams.category as PropertySearchFilters["category"],
   131→    publisherType: "",
   132→
   133→    // Options individuelles (compatibility)
   134→    hasGarden: false,
   135→    hasParking: false,
   136→    hasLift: false,
   137→    hasTerrace: false,
   138→    hasBalcony: false,
   139→    isNew: false,
   140→    isOld: false,
   141→    hasPriceChanged: false,
   142→
   143→    // Recherche textuelle
   144→    keywords: "",
   145→    keywordsOperator: "and" as const,
   146→
   147→    // Pagination et tri
   148→    page: urlParams.page,
   149→    sortBy: urlParams.sortBy as PropertySearchFilters["sortBy"],
   150→    sortOrder: urlParams.sortOrder,
   151→    view: urlParams.view,
   152→  };
   153→}
   154→
   155→export function filtersToUrlParams(
   156→  filters: PropertySearchFilters,
   157→): Partial<URLParams> {
   158→  return {
   159→    search: filters.search,
   160→    type: filters.type,
   161→    category: filters.category,
   162→    priceMin: filters.priceMin,
   163→    priceMax: filters.priceMax,
   164→    surfaceMin: filters.surfaceMin,
   165→    surfaceMax: filters.surfaceMax,
   166→    rooms: filters.rooms,
   167→    bedrooms: filters.bedrooms,
   168→    city: filters.city,
   169→    selectedCitiesJson: JSON.stringify(filters.selectedCities),
   170→    page: filters.page,
   171→    sortBy: filters.sortBy,
   172→    sortOrder: filters.sortOrder,
   173→    view: filters.view,
   174→  };
   175→}
