   690→          }
   691→        : undefined,
   692→
   693→      energyClass: this.nullToUndefined(moteurImmoProperty.energyGrade),
   694→      energyValue: this.nullToUndefined(moteurImmoProperty.energyValue),
   695→      gasClass: this.nullToUndefined(moteurImmoProperty.gasGrade),
   696→      gasValue: this.nullToUndefined(moteurImmoProperty.gasValue),
   697→
   698→      hasGarden: moteurImmoProperty.options?.includes("hasGarden") ?? false,
