   722→  private convertCategory(moteurImmoCategory: string): Property["category"] {
   723→    const categoryMap: Record<string, Property["category"]> = {
   724→      house: "house",
   725→      flat: "flat",
   726→      land: "land",
   727→      "parking/garage/box": "office", // Map parking to office category
   728→      office: "office",
   729→      shop: "shop",
   730→      warehouse: "warehouse",
   731→      building: "building",
