    17→
    18→    const enrichmentService = new FavoriteEnrichmentService();
    19→
    20→    switch (action) {
    21→      case "enrich-favorite": {
    22→        if (!favoriteId) {
    23→          return NextResponse.json({ error: "favoriteId is required" }, { status: 400 });
    24→        }
    25→
    26→        // Vérifier que le favori appartient à l'utilisateur
