    36→        if (!favorite) {
    37→          return NextResponse.json({ error: "Favorite not found or access denied" }, { status: 404 });
    38→        }
    39→
    40→        const result = await enrichmentService.enrichFavoriteWithDPE(favoriteId);
    41→        return NextResponse.json(result);
    42→      }
    43→
    44→      case "enrich-user-favorites": {
    45→        const targetUserId = userId ?? session.user.id;
    46→
    47→        // Vérifier les permissions
    48→        if (targetUserId !== session.user.id && session.user.role !== "admin") {
    49→          return NextResponse.json({ error: "Unauthorized to enrich other user's favorites" }, { status: 403 });
    50→        }
    51→
    52→        const userResults = await enrichmentService.enrichUserFavorites(targetUserId);
    53→        return NextResponse.json({
    54→          success: true,
    55→          results: userResults,
    56→          total: userResults.length,
    57→          successful: userResults.filter(r => r.success).length,
    58→          failed: userResults.filter(r => !r.success).length,
    59→        });
    60→      }
    61→
    62→      case "enrich-all-without-dpe": {
    63→        // Admin seulement
    64→        if (session.user.role !== "admin") {
    65→          return NextResponse.json({ error: "Unauthorized" }, { status: 403 });
    66→        }
    67→
    68→        const allResults = await enrichmentService.enrichAllFavoritesWithoutDPE();
    69→        return NextResponse.json({
    70→          success: true,
    71→          results: allResults,
    72→          total: allResults.length,
    73→          successful: allResults.filter(r => r.success).length,
    74→          failed: allResults.filter(r => !r.success).length,
    75→        });
    76→      }
    77→
    78→      default:
    79→        return NextResponse.json({ error: "Invalid action" }, { status: 400 });
    80→    }
    81→  } catch (error) {
